#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Stage owned, pinned media fixtures offline; optionally regenerate the tiny MPEG-4 clip."""
import argparse
import hashlib
import json
from pathlib import Path
import subprocess
import wave

VIDEO_SHA256 = '65d9570c01189231926f8a85779d02a224f6782ec5bc6d4c192d7dd84745463e'
parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('output', type=Path)
parser.add_argument('--regenerate-video', action='store_true',
                    help='Requires FFmpeg; generated bytes must match the pinned owned fixture')
args = parser.parse_args()
canonical = Path(__file__).with_name('green-64x48.mp4').read_bytes()
if hashlib.sha256(canonical).hexdigest() != VIDEO_SHA256:
    raise SystemExit('Owned MPEG-4 fixture differs from its pinned SHA-256; no output published.')
output = args.output
output.mkdir(parents=True, exist_ok=True)
video = output / 'green-64x48.mp4'
if args.regenerate_video:
    subprocess.run([
        'ffmpeg', '-v', 'error', '-f', 'lavfi', '-i', 'color=c=0x008000:s=64x48:r=5',
        '-t', '1', '-an', '-c:v', 'mpeg4', '-q:v', '2', '-pix_fmt', 'yuv420p',
        '-flags', '+bitexact', '-fflags', '+bitexact', '-y', str(video)
    ], check=True, timeout=30)
    if hashlib.sha256(video.read_bytes()).hexdigest() != VIDEO_SHA256:
        raise SystemExit('Regenerated bytes differ; inspect the candidate/tool version. Canonical source was not changed.')
else:
    video.write_bytes(canonical)
with wave.open(str(output / 'pcm-500ms.wav'), 'wb') as audio:
    audio.setnchannels(1)
    audio.setsampwidth(2)
    audio.setframerate(8000)
    audio.writeframes(b'\x00\x00' * 4000)
manifest = {
    'meaning': 'Owned generated fixtures, not inspected applications or third-party media.',
    'video': {'width': 64, 'height': 48, 'durationMs': 1000, 'rgb': '008000', 'codec': 'mpeg4'},
    'audio': {'durationMs': 500, 'sampleRate': 8000, 'channels': 1, 'codec': 'pcm_s16le'},
    'videoGeneratedWith': 'FFmpeg 7.1.5 (Debian 7.1.5-0+deb13u1), exact command retained in generator source',
    'videoRegeneratedThisBuild': args.regenerate_video,
    'pcmGeneratedWith': 'Python standard-library wave',
    'files': {p.name: hashlib.sha256(p.read_bytes()).hexdigest()
              for p in sorted(output.iterdir()) if p.suffix in ['.mp4', '.wav']},
}
(output / 'fixture-manifest.json').write_text(json.dumps(manifest, indent=2) + '\n')
print('Pinned owned 64×48 green video and generated 500 ms PCM fixtures staged offline.')
